selector_to_html = {"a[href=\"#pyskyfire.regen.coupled_solver.coupled_steady_heating_analysis\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.coupled_steady_heating_analysis\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">coupled_steady_heating_analysis</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thrust_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundary_conditions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nodes</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">100</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit_index</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#int\" title=\"(in Python v3.15)\"><span class=\"pre\">int</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'auto'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"FilmHeatFluxModel.html#pyskyfire.regen.coupled_solver.FilmHeatFluxModel\" title=\"pyskyfire.regen.coupled_solver.FilmHeatFluxModel\"><span class=\"pre\">FilmHeatFluxModel</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_liquid_wall</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">DEFAULT_H_LIQUID_WALL</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_x_array</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Sequence</span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">solver</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'newton'</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">output</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heat_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pressure_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"RegenResult.html#pyskyfire.regen.coupled_solver.RegenResult\" title=\"pyskyfire.regen.coupled_solver.RegenResult\"><span class=\"pre\">RegenResult</span></a></span></span></dt><dd><p>Run a steady heating analysis with film cooling, regen cooling, or both.</p></dd>", "a[href=\"../thrust_chamber/FilmCooling.html#pyskyfire.regen.thrust_chamber.FilmCooling\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.thrust_chamber.FilmCooling\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.thrust_chamber.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FilmCooling</span></span></dt><dd><p>User-facing film cooling inputs attached to a ThrustChamber.</p></dd>", "a[href=\"../film_solver/LiquidFilmResults.html#pyskyfire.regen.film_solver.LiquidFilmResults\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.film_solver.LiquidFilmResults\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.film_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">LiquidFilmResults</span></span></dt><dd></dd>", "a[href=\"#attributes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Attributes<a class=\"headerlink\" href=\"#attributes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../film_solver/GaseousFilmResults.html#pyskyfire.regen.film_solver.GaseousFilmResults\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.film_solver.GaseousFilmResults\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.film_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">GaseousFilmResults</span></span></dt><dd></dd>", "a[href=\"#how-the-coupling-works\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">How the coupling works<a class=\"headerlink\" href=\"#how-the-coupling-works\" title=\"Link to this heading\">\u00b6</a></h2><p>Every hot-side model in here reduces to a wall heat flux <code class=\"docutils literal notranslate\"><span class=\"pre\">qpp_hot</span></code>, so the\nwall/coolant stack downstream never needs to know which model produced it.\n<a class=\"reference internal\" href=\"FilmHeatFluxModel.html#pyskyfire.regen.coupled_solver.FilmHeatFluxModel\" title=\"pyskyfire.regen.coupled_solver.FilmHeatFluxModel\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">FilmHeatFluxModel</span></code></a> decides, per station, which one does:</p>", "a[href=\"#pyskyfire.regen.coupled_solver.DEFAULT_H_LIQUID_WALL\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.DEFAULT_H_LIQUID_WALL\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">DEFAULT_H_LIQUID_WALL</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">5000.0</span></span></dt><dd></dd>", "a[href=\"#the-one-empirical-knob-h-liquid-wall\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The one empirical knob: <code class=\"docutils literal notranslate\"><span class=\"pre\">h_liquid_wall</span></code><a class=\"headerlink\" href=\"#the-one-empirical-knob-h-liquid-wall\" title=\"Link to this heading\">\u00b6</a></h2><p>Behind a liquid film the wall is bathed in saturated liquid, so the driving\ntemperature collapses from the gas recovery temperature (thousands of kelvin)\nto <span class=\"math notranslate nohighlight\">\\(T_\\text{sat}\\)</span> (hundreds). What is <em>not</em> pinned down by the Grisson\nmodel is the film-to-wall conductance, because the model never resolves the\nfilm thickness. <code class=\"docutils literal notranslate\"><span class=\"pre\">h_liquid_wall</span></code> supplies it, defaulting to\n<a class=\"reference internal\" href=\"#pyskyfire.regen.coupled_solver.DEFAULT_H_LIQUID_WALL\" title=\"pyskyfire.regen.coupled_solver.DEFAULT_H_LIQUID_WALL\"><code class=\"xref py py-data docutils literal notranslate\"><span class=\"pre\">DEFAULT_H_LIQUID_WALL</span></code></a> \u2013 an order-of-magnitude estimate for a thin\nsaturated film (<span class=\"math notranslate nohighlight\">\\(k_l/\\delta\\)</span> with <span class=\"math notranslate nohighlight\">\\(k_l \\sim 0.15\\)</span>\nW m\u207b\u00b9 K\u207b\u00b9 and <span class=\"math notranslate nohighlight\">\\(\\delta \\sim 30\\)</span> \u00b5m). Set it very large (<code class=\"docutils literal notranslate\"><span class=\"pre\">1e6</span></code>) to\nrecover the textbook idealisation <span class=\"math notranslate nohighlight\">\\(T_\\text{hw} = T_\\text{sat}\\)</span>, or pass\na callable <code class=\"docutils literal notranslate\"><span class=\"pre\">h(x)</span></code> for a spatially varying estimate. It is the number to\ncalibrate first if you have wall-temperature data.</p><p>Note also that the film mass flow is <em>not</em> subtracted from the regenerative\ncircuit\u2019s mass flow here \u2013 set <code class=\"docutils literal notranslate\"><span class=\"pre\">BoundaryConditions.mdot_coolant</span></code> to whatever\nactually reaches the channels.</p>", "a[href=\"../../thermo/state/index.html#pyskyfire.thermo.state.probe_fluid\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.thermo.state.probe_fluid\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.thermo.state.</span></span><span class=\"sig-name descname\"><span class=\"pre\">probe_fluid</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fluid</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_ref</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"../../thermo/state/FluidCapability.html#pyskyfire.thermo.state.FluidCapability\" title=\"pyskyfire.thermo.state.FluidCapability\"><span class=\"pre\">FluidCapability</span></a></span></span></dt><dd><p>Determine what two-phase support a CoolProp fluid string has.</p><p>Run once per solve, at the inlet pressure. Cheap: a handful of property\ncalls.</p><p class=\"rubric\">Notes</p><p>The critical-pressure probe is deliberately tolerant. <code class=\"docutils literal notranslate\"><span class=\"pre\">Props1SI</span></code> refuses\nmixtures outright, and <code class=\"docutils literal notranslate\"><span class=\"pre\">AbstractState.p_critical()</span></code> can fail even for\nwell-behaved binaries (ethanol/water reports \u201cfound 4 critical points\u201d), so\na missing critical point downgrades the capability rather than raising.</p></dd>", "a[href=\"#module-pyskyfire.regen.coupled_solver\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.coupled_solver<a class=\"headerlink\" href=\"#module-pyskyfire.regen.coupled_solver\" title=\"Link to this heading\">\u00b6</a></h1><p>Coupled film + regenerative cooling solver.</p><p>The hot-side boundary condition can come from either the hot combustion gas,\na film cooling solution, or a mix of the two along the chamber.</p>", "a[href=\"#pyskyfire.regen.coupled_solver.solve_film_cooling\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.solve_film_cooling\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">solve_film_cooling</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thrust_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundary_conditions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x_array</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">Sequence</span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"../film_solver/LiquidFilmResults.html#pyskyfire.regen.film_solver.LiquidFilmResults\" title=\"pyskyfire.regen.film_solver.LiquidFilmResults\"><span class=\"pre\">LiquidFilmResults</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference internal\" href=\"../film_solver/GaseousFilmResults.html#pyskyfire.regen.film_solver.GaseousFilmResults\" title=\"pyskyfire.regen.film_solver.GaseousFilmResults\"><span class=\"pre\">GaseousFilmResults</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span></span></dt><dd><p>Run the film cooling model on its own.</p></dd>", "a[href=\"CoupledHeatExchangerPhysics.html#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.cold_side_coefficients\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.cold_side_coefficients\">\n<span class=\"sig-name descname\"><span class=\"pre\">cold_side_coefficients</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cw</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">T_cool</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">p_cool</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">quality</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Coolant-side heat transfer coefficient at <code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code>.</p><p>Coolant properties are evaluated at the local coolant pressure.</p><p class=\"rubric\">Notes</p><p>This is a <strong>single-phase</strong> correlation everywhere, including inside the\nboiling dome, where it is evaluated on saturated-liquid properties. It\ntherefore models neither flow-boiling enhancement nor dryout. See\n<a class=\"reference internal\" href=\"../coolant_properties/index.html#module-pyskyfire.regen.coolant_properties\" title=\"pyskyfire.regen.coolant_properties\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen.coolant_properties</span></code></a>.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.solve_coupled_heat_exchanger\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.solve_coupled_heat_exchanger\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">solve_coupled_heat_exchanger</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thrust_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundary_conditions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">nodes</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit_index</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">output</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"FilmHeatFluxModel.html#pyskyfire.regen.coupled_solver.FilmHeatFluxModel\" title=\"pyskyfire.regen.coupled_solver.FilmHeatFluxModel\"><span class=\"pre\">FilmHeatFluxModel</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">log_residuals</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heat_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pressure_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"RegenResult.html#pyskyfire.regen.coupled_solver.RegenResult\" title=\"pyskyfire.regen.coupled_solver.RegenResult\"><span class=\"pre\">RegenResult</span></a></span></span></dt><dd><p>Solve wall heating on detailed nodes coupled to lumped coolant nodes.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">nodes</span></code> is normalized immediately to three axial grids in the order\n<code class=\"docutils literal notranslate\"><span class=\"pre\">wall</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">heat_flux</span></code>, and <code class=\"docutils literal notranslate\"><span class=\"pre\">coolant</span></code>. An integer creates three equal\nuniform grids. A ragged three-item sequence permits different counts, and\na mapping with those three names provides the same capability without\nrelying on positional order.</p><p>Each coolant interval owns one or more wall nodes. The wall balances use\nthe interval\u2019s lumped coolant state; their coolant-side heat rates are\nintegrated over metal-node control volumes to advance the next coolant\nstate. This mirrors the Binder et al. RL10 hybrid model, where multiple\nmetal nodes were connected to each of five coolant segments.</p></dd>", "a[href=\"#pyskyfire.regen.coupled_solver.RESIDUAL_TOL\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.RESIDUAL_TOL\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RESIDUAL_TOL</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">0.0001</span></span></dt><dd></dd>", "a[href=\"#functions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Functions<a class=\"headerlink\" href=\"#functions\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../coolant_properties/index.html#module-pyskyfire.regen.coolant_properties\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.regen.coolant_properties<a class=\"headerlink\" href=\"#module-pyskyfire.regen.coolant_properties\" title=\"Link to this heading\">\u00b6</a></h1><p>Coolant film properties and two-phase modelling limits for the regenerative march.</p>", "a[href=\"../../common/friction/index.html#module-pyskyfire.common.friction\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.common.friction<a class=\"headerlink\" href=\"#module-pyskyfire.common.friction\" title=\"Link to this heading\">\u00b6</a></h1><p>Duct friction physics shared by cooling channels and piping.</p><p>This module is deliberately geometry-agnostic. Every entry point takes plain\nscalars \u2013 a Reynolds number, a hydraulic diameter, an absolute roughness, a\nsigned radius of curvature \u2013 so the same physics serves a regen cooling\nchannel marching on an axial coordinate and a pipe run marching on arc length.\nAnything that knows about contours, centerlines or stations belongs elsewhere.</p>", "a[href=\"#the-coolant-march-enthalpy-where-possible-temperature-otherwise\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">The coolant march: enthalpy where possible, temperature otherwise<a class=\"headerlink\" href=\"#the-coolant-march-enthalpy-where-possible-temperature-otherwise\" title=\"Link to this heading\">\u00b6</a></h2><p>The coolant state is advanced on <strong>specific enthalpy</strong>, so the march stays\nvalid through the boiling dome and reports vapour quality. Temperature is not a\nusable state variable there \u2013 inside the dome it is pinned to\n<span class=\"math notranslate nohighlight\">\\(T_\\text{sat}(p)\\)</span> while the fluid keeps absorbing heat \u2013 and a\ntemperature march stepping past saturation silently lands on the superheated\nvapour branch, with a ~19x density error. See\n<a class=\"reference internal\" href=\"../coolant_properties/index.html#module-pyskyfire.regen.coolant_properties\" title=\"pyskyfire.regen.coolant_properties\"><code class=\"xref py py-mod docutils literal notranslate\"><span class=\"pre\">pyskyfire.regen.coolant_properties</span></code></a> for the full argument and for what the\ntwo-phase treatment does and does not cover.</p><p>Two coolants keep the old temperature march, via\n<a class=\"reference internal\" href=\"../../thermo/state/index.html#pyskyfire.thermo.state.probe_fluid\" title=\"pyskyfire.thermo.state.probe_fluid\"><code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">probe_fluid()</span></code></a>:</p>", "a[href=\"#pyskyfire.regen.coupled_solver.SATURATION_NUDGE\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.SATURATION_NUDGE\">\n<span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">SATURATION_NUDGE</span></span><span class=\"property\"><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"pre\">0.001</span></span></dt><dd></dd>", "a[href=\"CoupledHeatExchangerPhysics.html#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">CoupledHeatExchangerPhysics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">thrust_chamber</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">boundary_conditions</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">circuit_index</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">film_model</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">coolant_state</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../../thermo/state/FluidStateResolver.html#pyskyfire.thermo.state.FluidStateResolver\" title=\"pyskyfire.thermo.state.FluidStateResolver\"><span class=\"pre\">FluidStateResolver</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">heat_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">pressure_curvature_correction</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#bool\" title=\"(in Python v3.15)\"><span class=\"pre\">bool</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">friction_model</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#str\" title=\"(in Python v3.15)\"><span class=\"pre\">str</span></a></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">'native'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Heat-exchanger physics whose hot side may be gas- or film-driven.</p><p>The bare-wall hot side uses the enthalpy-driven Bartz model. Where a film\ncovers the wall, <a class=\"reference internal\" href=\"#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.hot_side_coefficients\" title=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.hot_side_coefficients\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">hot_side_coefficients()</span></code></a> substitutes the appropriate\nliquid- or gaseous-film boundary condition. The shared wall, coolant, and\npressure models consume the resulting <code class=\"docutils literal notranslate\"><span class=\"pre\">qpp_hot</span></code> regardless of its source.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"#module-contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Module Contents<a class=\"headerlink\" href=\"#module-contents\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"FilmHeatFluxModel.html#pyskyfire.regen.coupled_solver.FilmHeatFluxModel\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.FilmHeatFluxModel\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">FilmHeatFluxModel</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">liquid_results</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../film_solver/LiquidFilmResults.html#pyskyfire.regen.film_solver.LiquidFilmResults\" title=\"pyskyfire.regen.film_solver.LiquidFilmResults\"><span class=\"pre\">LiquidFilmResults</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">gaseous_results</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"../film_solver/GaseousFilmResults.html#pyskyfire.regen.film_solver.GaseousFilmResults\" title=\"pyskyfire.regen.film_solver.GaseousFilmResults\"><span class=\"pre\">GaseousFilmResults</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/constants.html#None\" title=\"(in Python v3.15)\"><span class=\"pre\">None</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">x_injection</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">h_liquid_wall</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">DEFAULT_H_LIQUID_WALL</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Turn a Grisson film solution into a hot-side boundary condition.</p><p class=\"rubric\">Notes</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">x</span></code> outside the solved film range is clamped to the nearest solved\nstation, so a regenerative grid finer than the film grid is fine.</p></dd>", "a[href=\"RegenResult.html#pyskyfire.regen.coupled_solver.RegenResult\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.RegenResult\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RegenResult</span></span></dt><dd><p>Regenerative-cooling result with optional film-cooling data.</p><p>The coolant-state fields (<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_enthalpy</span></code> onwards) describe the bulk\ncoolant along the circuit. <code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_enthalpy</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_quality</span></code> are\nall-<code class=\"docutils literal notranslate\"><span class=\"pre\">nan</span></code> when the coolant fell back to the temperature march, and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_quality</span></code> is <code class=\"docutils literal notranslate\"><span class=\"pre\">nan</span></code> at any station outside the boiling dome \u2013\nincluding supercritical stations, where no dome exists. Use\n<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_phase</span></code> to tell those cases apart.</p></dd>", "a[href=\"#coolant-properties-are-evaluated-at-the-coolant-pressure\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Coolant properties are evaluated at the coolant pressure<a class=\"headerlink\" href=\"#coolant-properties-are-evaluated-at-the-coolant-pressure\" title=\"Link to this heading\">\u00b6</a></h2><p><a class=\"reference internal\" href=\"CoupledHeatExchangerPhysics.html#pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.cold_side_coefficients\" title=\"pyskyfire.regen.coupled_solver.CoupledHeatExchangerPhysics.cold_side_coefficients\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">CoupledHeatExchangerPhysics.cold_side_coefficients()</span></code></a> evaluates the\ncoolant film properties at the coolant pressure. The coolant pressure is what\nthe march already tracks and what <code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_friction_rate</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">coolant_enthalpy_rate</span></code> already use, so it is threaded through here too.</p>", "a[href=\"BoundaryConditions.html#pyskyfire.regen.coupled_solver.BoundaryConditions\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.regen.coupled_solver.BoundaryConditions\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.regen.coupled_solver.</span></span><span class=\"sig-name descname\"><span class=\"pre\">BoundaryConditions</span></span></dt><dd><p>Boundary conditions for the coolant-side inlet.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
